/**
 * 插件管理器
 *
 * 負責插件的註冊、依賴解析和生命週期管理
 * 借鏡 Video.js 的插件系統設計
 */

import type {
    MpvPlugin,
    PluginInstance,
    PluginEntry,
    IPluginManager,
} from './types/plugin';
import type { MpvVideoElement } from '../renderer/ui/MpvVideoElement';
import { PluginEventBus, IPluginEventBus } from './PluginEventBus';
import { PluginConfigStorage, IPluginConfigStorage } from './PluginConfig';

/**
 * 插件管理器實現
 */
export class PluginManager implements IPluginManager {
    /** 已安裝的插件實例 */
    private plugins: Map<string, PluginInstance> = new Map();

    /** 播放器實例引用 */
    private player: MpvVideoElement;

    /** 安裝順序記錄（用於正確的銷毀順序） */
    private installOrder: string[] = [];

    /** 已注入的樣式元素（用於清理） */
    private styleElements: Map<string, HTMLStyleElement> = new Map();

    /** 插件事件總線（用於插件間通信） */
    private readonly eventBus: PluginEventBus;

    /** 插件配置存儲 */
    private readonly configStorage: PluginConfigStorage;

    constructor(player: MpvVideoElement) {
        this.player = player;
        this.eventBus = new PluginEventBus();
        this.configStorage = new PluginConfigStorage();
    }

    /**
     * 獲取插件事件總線
     * 用於插件間通信
     */
    get events(): IPluginEventBus {
        return this.eventBus;
    }

    /**
     * 獲取插件配置存儲
     * 用於持久化插件配置
     */
    get config(): IPluginConfigStorage {
        return this.configStorage;
    }

    /**
     * 注入插件樣式到 Shadow DOM
     * @param pluginName - 插件名稱
     * @param styles - CSS 樣式字符串
     */
    private injectStyles(pluginName: string, styles: string): void {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) {
            console.warn(`[PluginManager] Cannot inject styles for "${pluginName}": no shadowRoot`);
            return;
        }

        // 檢查是否已注入
        if (this.styleElements.has(pluginName)) {
            return;
        }

        const styleEl = document.createElement('style');
        styleEl.setAttribute('data-plugin', pluginName);
        styleEl.textContent = styles;
        shadowRoot.appendChild(styleEl);

        this.styleElements.set(pluginName, styleEl);
        console.log(`[PluginManager] Styles injected for plugin "${pluginName}"`);
    }

    /**
     * 移除插件樣式
     * @param pluginName - 插件名稱
     */
    private removeStyles(pluginName: string): void {
        const styleEl = this.styleElements.get(pluginName);
        if (styleEl) {
            styleEl.remove();
            this.styleElements.delete(pluginName);
        }
    }

    /**
     * 註冊並安裝插件
     * @param plugin - 插件定義
     * @param options - 插件選項
     * @returns 插件實例或 undefined
     */
    register<T>(plugin: MpvPlugin<T>, options?: T): PluginInstance | void {
        const { name, dependencies } = plugin;

        // 檢查是否已安裝
        if (this.plugins.has(name)) {
            console.warn(`[PluginManager] Plugin "${name}" is already installed`);
            return this.plugins.get(name);
        }

        // 檢查依賴
        if (dependencies && dependencies.length > 0) {
            for (const dep of dependencies) {
                if (!this.plugins.has(dep)) {
                    throw new Error(
                        `[PluginManager] Plugin "${name}" requires "${dep}" to be installed first`
                    );
                }
            }
        }

        // 注入插件樣式（在安裝之前，確保 DOM 創建時樣式已就緒）
        if (plugin.styles) {
            this.injectStyles(name, plugin.styles);
        }

        // 安裝插件
        try {
            const instance = plugin.install(this.player, options);

            if (instance) {
                this.plugins.set(name, instance);
                this.installOrder.push(name);

                // 在播放器上暴露插件（支持 player.myPlugin.method() 調用）
                if (!(name in this.player)) {
                    Object.defineProperty(this.player, name, {
                        value: instance,
                        writable: false,
                        configurable: true,
                    });
                }

                console.log(`[PluginManager] Plugin "${name}" installed`);
            }

            return instance;
        } catch (error) {
            // 安裝失敗時清理已注入的樣式
            this.removeStyles(name);
            console.error(`[PluginManager] Failed to install plugin "${name}":`, error);
            throw error;
        }
    }

    /**
     * 獲取已安裝的插件實例
     * @param name - 插件名稱
     */
    get<T extends PluginInstance = PluginInstance>(name: string): T | undefined {
        return this.plugins.get(name) as T | undefined;
    }

    /**
     * 檢查插件是否已安裝
     * @param name - 插件名稱
     */
    has(name: string): boolean {
        return this.plugins.has(name);
    }

    /**
     * 銷毀指定插件
     * @param name - 插件名稱
     */
    destroy(name: string): boolean {
        const instance = this.plugins.get(name);
        if (!instance) {
            return false;
        }

        try {
            // 調用插件的銷毀方法
            instance.destroy?.();

            // 移除插件樣式
            this.removeStyles(name);

            // 從播放器上移除引用
            if (name in this.player) {
                delete (this.player as unknown as Record<string, unknown>)[name];
            }

            // 從註冊表移除
            this.plugins.delete(name);

            // 從安裝順序中移除
            const index = this.installOrder.indexOf(name);
            if (index !== -1) {
                this.installOrder.splice(index, 1);
            }

            console.log(`[PluginManager] Plugin "${name}" destroyed`);
            return true;
        } catch (error) {
            console.error(`[PluginManager] Failed to destroy plugin "${name}":`, error);
            return false;
        }
    }

    /**
     * 銷毀所有插件
     * 按照安裝的相反順序銷毀（後安裝的先銷毀）
     */
    destroyAll(): void {
        // 複製並反轉順序
        const destroyOrder = [...this.installOrder].reverse();

        for (const name of destroyOrder) {
            this.destroy(name);
        }

        // 清理事件總線
        this.eventBus.removeAllListeners();
    }

    /**
     * 切換插件狀態的內部方法
     */
    private togglePluginState(name: string, action: 'enable' | 'disable'): boolean {
        const instance = this.plugins.get(name);
        if (!instance) return false;

        try {
            instance[action]?.();
            return true;
        } catch (error) {
            console.error(`[PluginManager] Failed to ${action} plugin "${name}":`, error);
            return false;
        }
    }

    /**
     * 禁用指定插件
     * @param name - 插件名稱
     */
    disable(name: string): boolean {
        return this.togglePluginState(name, 'disable');
    }

    /**
     * 啟用指定插件
     * @param name - 插件名稱
     */
    enable(name: string): boolean {
        return this.togglePluginState(name, 'enable');
    }

    /**
     * 獲取所有已安裝插件的名稱
     */
    getInstalledPlugins(): string[] {
        return [...this.installOrder];
    }

    /**
     * 獲取插件數量
     */
    get count(): number {
        return this.plugins.size;
    }
}

/**
 * 全局插件註冊表
 * 用於存儲通過 MpvVideoElement.use() 註冊的全局插件
 */
export class GlobalPluginRegistry {
    private static entries: PluginEntry[] = [];
    /** 使用 Set 實現 O(1) 查找已註冊的插件名稱 */
    private static registeredNames: Set<string> = new Set();

    /**
     * 註冊全局插件
     */
    static register<T>(plugin: MpvPlugin<T>, options?: T): void {
        // 使用 Set 實現 O(1) 查找
        if (this.registeredNames.has(plugin.name)) {
            console.warn(`[GlobalPluginRegistry] Plugin "${plugin.name}" is already registered`);
            return;
        }

        this.registeredNames.add(plugin.name);
        this.entries.push({ plugin, options });
    }

    /**
     * 批量註冊全局插件
     */
    static registerAll(plugins: Array<MpvPlugin | PluginEntry>): void {
        for (const item of plugins) {
            if ('install' in item) {
                // 是 MpvPlugin
                this.register(item);
            } else {
                // 是 PluginEntry
                this.register(item.plugin, item.options);
            }
        }
    }

    /**
     * 獲取所有已註冊的全局插件
     */
    static getAll(): PluginEntry[] {
        return [...this.entries];
    }

    /**
     * 清空全局插件註冊表
     */
    static clear(): void {
        this.entries = [];
        this.registeredNames.clear();
    }

    /**
     * 將全局插件安裝到播放器實例
     */
    static installTo(pluginManager: PluginManager): void {
        console.log(`[GlobalPluginRegistry] Installing ${this.entries.length} plugins`);
        for (const { plugin, options } of this.entries) {
            console.log(`[GlobalPluginRegistry] Installing plugin: ${plugin.name}`);
            pluginManager.register(plugin, options);
        }
    }
}

/**
 * 創建插件工廠
 * 簡化插件定義的創建
 */
export function definePlugin<T = void>(
    name: string,
    installer: (player: MpvVideoElement, options?: T) => PluginInstance | void,
    meta?: { version?: string; dependencies?: string[] }
): MpvPlugin<T> {
    return {
        name,
        version: meta?.version,
        dependencies: meta?.dependencies,
        install: installer,
    };
}

/**
 * 創建簡單插件
 * 適用於不需要返回實例的插件
 */
export function createSimplePlugin<T = void>(
    name: string,
    setup: (player: MpvVideoElement, options?: T) => void | (() => void),
    meta?: { version?: string; dependencies?: string[] }
): MpvPlugin<T> {
    return definePlugin(name, (player, options) => {
        const cleanup = setup(player, options);

        return {
            name,
            destroy: cleanup || undefined,
        };
    }, meta);
}
