/**
 * 響應式狀態管理
 *
 * 提供 Signal 模式的響應式狀態，支援細粒度訂閱
 * 借鏡 Vidstack 的狀態管理設計
 */

import type {
    ISignal,
    MediaState,
    MediaStateSnapshot,
    StateSubscriber,
    Unsubscribe,
    ReadyState,
    NetworkState,
} from './types/state';

// 重新導出類型供外部使用
export type { MediaState, MediaStateSnapshot } from './types/state';

/**
 * 響應式信號實現
 * 當值變化時自動通知所有訂閱者
 */
export class Signal<T> implements ISignal<T> {
    private value: T;
    private subscribers: Set<StateSubscriber<T>> = new Set();

    constructor(initialValue: T) {
        this.value = initialValue;
    }

    /**
     * 獲取當前值
     */
    get(): T {
        return this.value;
    }

    /**
     * 設置新值，如果值變化則通知訂閱者
     */
    set(newValue: T): void {
        const previousValue = this.value;
        if (!Object.is(previousValue, newValue)) {
            this.value = newValue;
            this.notify(previousValue);
        }
    }

    /**
     * 強制設置值並通知（即使值相同）
     */
    forceSet(newValue: T): void {
        const previousValue = this.value;
        this.value = newValue;
        this.notify(previousValue);
    }

    /**
     * 訂閱狀態變化
     * @param callback - 狀態變化時的回調
     * @param immediate - 是否立即執行一次回調（默認 false）
     * @returns 取消訂閱函數
     */
    subscribe(callback: StateSubscriber<T>, immediate = false): Unsubscribe {
        this.subscribers.add(callback);

        if (immediate) {
            callback(this.value, this.value);
        }

        return () => {
            this.subscribers.delete(callback);
        };
    }

    /**
     * 當前訂閱者數量
     */
    get subscriberCount(): number {
        return this.subscribers.size;
    }

    /**
     * 通知所有訂閱者
     */
    private notify(previousValue: T): void {
        for (const subscriber of this.subscribers) {
            try {
                subscriber(this.value, previousValue);
            } catch (error) {
                console.error('[Signal] Subscriber error:', error);
            }
        }
    }
}

/**
 * 批量更新上下文
 * 在批量更新中，所有狀態變化會被收集，最後一起通知
 */
let isBatching = false;
const pendingNotifications: Array<() => void> = [];

/**
 * 批量更新狀態
 * 避免多次狀態變化導致多次通知
 *
 * @example
 * batchUpdate(() => {
 *   state.paused.set(false);
 *   state.playing.set(true);
 * });
 */
export function batchUpdate(fn: () => void): void {
    if (isBatching) {
        fn();
        return;
    }

    isBatching = true;
    try {
        fn();
    } finally {
        isBatching = false;
        // 執行所有待處理的通知
        const notifications = pendingNotifications.splice(0);
        for (const notify of notifications) {
            notify();
        }
    }
}

/**
 * 創建媒體狀態存儲
 * 包含所有播放器相關的響應式狀態
 */
export function createMediaState(): MediaState {
    return {
        // 播放狀態
        paused: new Signal(true),
        playing: new Signal(false),
        ended: new Signal(false),
        seeking: new Signal(false),
        waiting: new Signal(false),

        // 時間
        currentTime: new Signal(0),
        duration: new Signal(0),
        buffered: new Signal(0),

        // 音量
        volume: new Signal(1),
        muted: new Signal(false),

        // 播放速率
        playbackRate: new Signal(1),
        defaultPlaybackRate: new Signal(1),

        // 尺寸
        videoWidth: new Signal(0),
        videoHeight: new Signal(0),

        // 載入狀態
        readyState: new Signal(0 as ReadyState),
        networkState: new Signal(0 as NetworkState),

        // 來源
        src: new Signal(''),

        // 循環
        loop: new Signal(false),

        // HDR
        isHdr: new Signal(false),
        hdrModeEnabled: new Signal(false),

        // FPS
        fps: new Signal(24),

        // 全螢幕
        fullscreen: new Signal(false),
    };
}

/**
 * 獲取狀態快照
 * 將所有 Signal 的當前值提取為普通對象
 */
export function getStateSnapshot(state: MediaState): MediaStateSnapshot {
    return {
        paused: state.paused.get(),
        playing: state.playing.get(),
        ended: state.ended.get(),
        seeking: state.seeking.get(),
        waiting: state.waiting.get(),
        currentTime: state.currentTime.get(),
        duration: state.duration.get(),
        buffered: state.buffered.get(),
        volume: state.volume.get(),
        muted: state.muted.get(),
        playbackRate: state.playbackRate.get(),
        defaultPlaybackRate: state.defaultPlaybackRate.get(),
        videoWidth: state.videoWidth.get(),
        videoHeight: state.videoHeight.get(),
        readyState: state.readyState.get(),
        networkState: state.networkState.get(),
        src: state.src.get(),
        loop: state.loop.get(),
        isHdr: state.isHdr.get(),
        hdrModeEnabled: state.hdrModeEnabled.get(),
        fps: state.fps.get(),
        fullscreen: state.fullscreen.get(),
    };
}

/**
 * 從快照恢復狀態
 */
export function restoreStateFromSnapshot(state: MediaState, snapshot: Partial<MediaStateSnapshot>): void {
    batchUpdate(() => {
        for (const key of Object.keys(snapshot) as Array<keyof MediaStateSnapshot>) {
            const value = snapshot[key];
            if (value !== undefined && key in state) {
                (state[key] as ISignal<typeof value>).set(value);
            }
        }
    });
}

/**
 * 計算屬性
 * 基於其他 Signal 計算的衍生值
 */
export function computed<T>(getter: () => T, dependencies: Array<ISignal<unknown>>): ISignal<T> {
    const signal = new Signal(getter());

    // 訂閱所有依賴，當任一變化時重新計算
    for (const dep of dependencies) {
        dep.subscribe(() => {
            signal.set(getter());
        });
    }

    return signal;
}
