/**
 * 事件總線
 *
 * 提供類型安全的事件發布/訂閱機制
 * 兼容 DOM EventTarget API 風格
 */

import type {
    EventHandler,
    EventUnsubscribe,
    MediaEventMap,
    AllEventMap,
} from './types/events';

/**
 * 類型安全的事件總線實現
 * @template EventMap - 事件類型映射
 */
export class EventBus<EventMap extends object = AllEventMap>
{
    private handlers: Map<keyof EventMap, Set<EventHandler<unknown>>> = new Map();

    /**
     * 訂閱事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @returns 取消訂閱函數
     */
    on<K extends keyof EventMap>(event: K, handler: EventHandler<EventMap[K]>): EventUnsubscribe {
        if (!this.handlers.has(event)) {
            this.handlers.set(event, new Set());
        }
        this.handlers.get(event)!.add(handler as EventHandler<unknown>);

        return () => this.off(event, handler);
    }

    /**
     * 取消訂閱事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     */
    off<K extends keyof EventMap>(event: K, handler: EventHandler<EventMap[K]>): void {
        this.handlers.get(event)?.delete(handler as EventHandler<unknown>);
    }

    /**
     * 訂閱一次性事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @returns 取消訂閱函數
     */
    once<K extends keyof EventMap>(event: K, handler: EventHandler<EventMap[K]>): EventUnsubscribe {
        const wrapper: EventHandler<EventMap[K]> = (data) => {
            this.off(event, wrapper);
            handler(data);
        };
        return this.on(event, wrapper);
    }

    /**
     * 觸發事件
     * @param event - 事件名稱
     * @param data - 事件數據
     */
    emit<K extends keyof EventMap>(event: K, data: EventMap[K]): void {
        const handlers = this.handlers.get(event);
        if (!handlers) return;

        for (const handler of handlers) {
            try {
                handler(data);
            } catch (error) {
                console.error(`[EventBus] Error in handler for event "${String(event)}":`, error);
            }
        }
    }

    /**
     * 檢查是否有指定事件的監聽器
     * @param event - 事件名稱
     */
    hasListeners<K extends keyof EventMap>(event: K): boolean {
        return (this.handlers.get(event)?.size ?? 0) > 0;
    }

    /**
     * 移除指定事件的所有監聽器
     * @param event - 事件名稱
     */
    removeListeners<K extends keyof EventMap>(event: K): void {
        this.handlers.delete(event);
    }

    /**
     * 移除所有事件監聯器
     */
    removeAllListeners(): void {
        this.handlers.clear();
    }

    /**
     * 獲取指定事件的監聽器數量
     * @param event - 事件名稱
     */
    listenerCount<K extends keyof EventMap>(event: K): number {
        return this.handlers.get(event)?.size ?? 0;
    }

    /**
     * 獲取所有已註冊的事件名稱
     */
    eventNames(): Array<keyof EventMap> {
        return Array.from(this.handlers.keys());
    }
}

/**
 * 媒體事件總線
 * 專用於媒體相關事件
 */
export class MediaEventBus extends EventBus<MediaEventMap> {
    /**
     * 觸發媒體事件並同時派發 DOM 事件
     * @param target - DOM 事件目標元素
     * @param event - 事件名稱
     * @param data - 事件數據
     */
    emitWithDOM<K extends keyof MediaEventMap>(
        target: EventTarget,
        event: K,
        data: MediaEventMap[K]
    ): void {
        // 觸發內部事件
        this.emit(event, data);

        // 派發 DOM 事件
        const domEvent = new CustomEvent(String(event), {
            detail: data,
            bubbles: true,
            cancelable: true,
        });
        target.dispatchEvent(domEvent);
    }
}

/**
 * 創建帶有事件代理的事件總線
 * 允許將事件轉發到另一個 EventTarget
 */
export function createProxyEventBus<EventMap extends object>(
    target: EventTarget
): EventBus<EventMap> & { proxyTo(target: EventTarget): void } {
    const bus = new EventBus<EventMap>();
    let proxyTarget = target;

    // 代理所有事件到 DOM EventTarget
    const originalEmit = bus.emit.bind(bus);
    bus.emit = <K extends keyof EventMap>(event: K, data: EventMap[K]) => {
        originalEmit(event, data);

        // 同時派發 DOM 事件
        const domEvent = new CustomEvent(String(event), {
            detail: data,
            bubbles: true,
            cancelable: true,
        });
        proxyTarget.dispatchEvent(domEvent);
    };

    return Object.assign(bus, {
        proxyTo(newTarget: EventTarget) {
            proxyTarget = newTarget;
        },
    });
}

/**
 * 事件節流器
 * 限制事件觸發頻率
 */
export function throttleEvent<T>(
    handler: EventHandler<T>,
    interval: number
): EventHandler<T> {
    let lastTime = 0;
    let scheduled = false;
    let lastData: T;

    return (data: T) => {
        lastData = data;
        const now = Date.now();

        if (now - lastTime >= interval) {
            lastTime = now;
            handler(data);
        } else if (!scheduled) {
            scheduled = true;
            setTimeout(() => {
                scheduled = false;
                lastTime = Date.now();
                handler(lastData);
            }, interval - (now - lastTime));
        }
    };
}

/**
 * 事件防抖器
 * 只在事件停止觸發後執行
 */
export function debounceEvent<T>(
    handler: EventHandler<T>,
    delay: number
): EventHandler<T> {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    return (data: T) => {
        if (timeoutId !== null) {
            clearTimeout(timeoutId);
        }
        timeoutId = setTimeout(() => {
            timeoutId = null;
            handler(data);
        }, delay);
    };
}
