/**
 * 插件事件總線
 *
 * 提供插件間通信的事件系統
 * 支援類型安全的事件發送和訂閱
 */

/**
 * 事件處理器類型
 */
export type PluginEventHandler<T = unknown> = (data: T) => void;

/**
 * 取消訂閱函數
 */
export type PluginEventUnsubscribe = () => void;

/**
 * 內建插件事件類型
 */
export interface PluginEventMap {
    // 進度條相關事件
    'progress:seek': { time: number };
    'progress:scrubstart': void;
    'progress:scrubend': { time: number };

    // 音量相關事件
    'volume:change': { volume: number; muted: boolean };
    'volume:mute': void;
    'volume:unmute': void;

    // 播放相關事件
    'playback:ratechange': { rate: number };

    // 全螢幕相關事件
    'fullscreen:enter': void;
    'fullscreen:exit': void;

    // 自定義事件（用於第三方插件）
    [key: `custom:${string}`]: unknown;
}

/**
 * 插件事件總線接口
 */
export interface IPluginEventBus {
    /**
     * 發送事件
     * @param event - 事件名稱
     * @param data - 事件數據
     */
    emit<K extends keyof PluginEventMap>(event: K, data: PluginEventMap[K]): void;

    /**
     * 訂閱事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @returns 取消訂閱函數
     */
    on<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): PluginEventUnsubscribe;

    /**
     * 訂閱一次性事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @returns 取消訂閱函數
     */
    once<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): PluginEventUnsubscribe;

    /**
     * 取消訂閱事件
     * @param event - 事件名稱
     * @param handler - 事件處理器
     */
    off<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): void;

    /**
     * 檢查是否有指定事件的監聽器
     * @param event - 事件名稱
     */
    hasListeners<K extends keyof PluginEventMap>(event: K): boolean;

    /**
     * 移除所有事件監聽器
     */
    removeAllListeners(): void;
}

/**
 * 插件事件總線實現
 */
export class PluginEventBus implements IPluginEventBus {
    private listeners: Map<string, Set<PluginEventHandler<unknown>>> = new Map();

    emit<K extends keyof PluginEventMap>(event: K, data: PluginEventMap[K]): void {
        const handlers = this.listeners.get(event as string);
        if (!handlers || handlers.size === 0) return;

        for (const handler of handlers) {
            try {
                handler(data);
            } catch (error) {
                console.error(`[PluginEventBus] Error in event handler for "${event as string}":`, error);
            }
        }
    }

    on<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): PluginEventUnsubscribe {
        const eventKey = event as string;

        if (!this.listeners.has(eventKey)) {
            this.listeners.set(eventKey, new Set());
        }

        const handlers = this.listeners.get(eventKey)!;
        handlers.add(handler as PluginEventHandler<unknown>);

        // 返回取消訂閱函數
        return () => {
            handlers.delete(handler as PluginEventHandler<unknown>);
            if (handlers.size === 0) {
                this.listeners.delete(eventKey);
            }
        };
    }

    once<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): PluginEventUnsubscribe {
        const wrappedHandler: PluginEventHandler<PluginEventMap[K]> = (data) => {
            unsubscribe();
            handler(data);
        };

        const unsubscribe = this.on(event, wrappedHandler);
        return unsubscribe;
    }

    off<K extends keyof PluginEventMap>(
        event: K,
        handler: PluginEventHandler<PluginEventMap[K]>
    ): void {
        const eventKey = event as string;
        const handlers = this.listeners.get(eventKey);

        if (handlers) {
            handlers.delete(handler as PluginEventHandler<unknown>);
            if (handlers.size === 0) {
                this.listeners.delete(eventKey);
            }
        }
    }

    hasListeners<K extends keyof PluginEventMap>(event: K): boolean {
        const handlers = this.listeners.get(event as string);
        return handlers !== undefined && handlers.size > 0;
    }

    removeAllListeners(): void {
        this.listeners.clear();
    }

    /**
     * 獲取所有事件名稱（用於調試）
     */
    getEventNames(): string[] {
        return [...this.listeners.keys()];
    }

    /**
     * 獲取指定事件的監聽器數量
     */
    getListenerCount<K extends keyof PluginEventMap>(event: K): number {
        const handlers = this.listeners.get(event as string);
        return handlers?.size ?? 0;
    }
}

/**
 * 創建插件事件總線實例
 */
export function createPluginEventBus(): IPluginEventBus {
    return new PluginEventBus();
}
