/**
 * 插件配置持久化
 *
 * 提供插件配置的存儲和讀取功能
 * 支援 localStorage 和自定義存儲後端
 */

/**
 * 存儲後端接口
 */
export interface StorageBackend {
    getItem(key: string): string | null;
    setItem(key: string, value: string): void;
    removeItem(key: string): void;
}

/**
 * 插件配置存儲接口
 */
export interface IPluginConfigStorage {
    /**
     * 獲取插件配置值
     * @param pluginName - 插件名稱
     * @param key - 配置鍵
     * @param defaultValue - 默認值
     */
    get<T>(pluginName: string, key: string, defaultValue?: T): T | undefined;

    /**
     * 設置插件配置值
     * @param pluginName - 插件名稱
     * @param key - 配置鍵
     * @param value - 配置值
     */
    set<T>(pluginName: string, key: string, value: T): void;

    /**
     * 刪除插件配置值
     * @param pluginName - 插件名稱
     * @param key - 配置鍵
     */
    remove(pluginName: string, key: string): void;

    /**
     * 獲取插件所有配置
     * @param pluginName - 插件名稱
     */
    getAll(pluginName: string): Record<string, unknown>;

    /**
     * 清除插件所有配置
     * @param pluginName - 插件名稱
     */
    clear(pluginName: string): void;
}

/**
 * 插件配置存儲鍵前綴
 */
const STORAGE_PREFIX = 'mpv-plugin:';

/**
 * 插件配置存儲實現
 */
export class PluginConfigStorage implements IPluginConfigStorage {
    private storage: StorageBackend;
    private cache: Map<string, Record<string, unknown>> = new Map();

    constructor(storage?: StorageBackend) {
        // 默認使用 localStorage，如果不可用則使用內存存儲
        if (storage) {
            this.storage = storage;
        } else if (typeof localStorage !== 'undefined') {
            this.storage = localStorage;
        } else {
            // 內存存儲（用於非瀏覽器環境或 localStorage 不可用時）
            const memoryStorage: Record<string, string> = {};
            this.storage = {
                getItem: (key) => memoryStorage[key] ?? null,
                setItem: (key, value) => { memoryStorage[key] = value; },
                removeItem: (key) => { delete memoryStorage[key]; },
            };
        }
    }

    /**
     * 獲取存儲鍵
     */
    private getStorageKey(pluginName: string): string {
        return `${STORAGE_PREFIX}${pluginName}`;
    }

    /**
     * 從存儲加載插件配置
     */
    private loadPluginConfig(pluginName: string): Record<string, unknown> {
        // 檢查緩存
        if (this.cache.has(pluginName)) {
            return this.cache.get(pluginName)!;
        }

        const key = this.getStorageKey(pluginName);
        const raw = this.storage.getItem(key);

        let config: Record<string, unknown> = {};
        if (raw) {
            try {
                config = JSON.parse(raw);
            } catch (error) {
                console.warn(`[PluginConfig] Failed to parse config for "${pluginName}":`, error);
            }
        }

        this.cache.set(pluginName, config);
        return config;
    }

    /**
     * 保存插件配置到存儲
     */
    private savePluginConfig(pluginName: string, config: Record<string, unknown>): void {
        const key = this.getStorageKey(pluginName);
        try {
            this.storage.setItem(key, JSON.stringify(config));
            this.cache.set(pluginName, config);
        } catch (error) {
            console.error(`[PluginConfig] Failed to save config for "${pluginName}":`, error);
        }
    }

    get<T>(pluginName: string, key: string, defaultValue?: T): T | undefined {
        const config = this.loadPluginConfig(pluginName);
        const value = config[key];
        return value !== undefined ? (value as T) : defaultValue;
    }

    set<T>(pluginName: string, key: string, value: T): void {
        const config = this.loadPluginConfig(pluginName);
        config[key] = value;
        this.savePluginConfig(pluginName, config);
    }

    remove(pluginName: string, key: string): void {
        const config = this.loadPluginConfig(pluginName);
        delete config[key];
        this.savePluginConfig(pluginName, config);
    }

    getAll(pluginName: string): Record<string, unknown> {
        return { ...this.loadPluginConfig(pluginName) };
    }

    clear(pluginName: string): void {
        const key = this.getStorageKey(pluginName);
        this.storage.removeItem(key);
        this.cache.delete(pluginName);
    }

    /**
     * 清除所有插件配置
     */
    clearAll(): void {
        // 無法遍歷所有存儲項，只能清除緩存
        this.cache.clear();
    }
}

/**
 * 創建插件配置存儲實例
 */
export function createPluginConfigStorage(storage?: StorageBackend): IPluginConfigStorage {
    return new PluginConfigStorage(storage);
}
